#include "../../support/official.hpp"
#include "../support/diag_state.hpp"
using namespace p3official;
struct Case{std::string mesh;size_t id;Real alpha,theta,c;};
int main(int argc,char**argv){try{if(argc!=7)throw std::runtime_error("usage: diag_D3 config selected.tsv output level nx ny");gss::SlepcContext slepc;auto settings=load_settings(argv[1]);auto config=gss::YAMLConfig::load(argv[1]);auto study=ps::load_study_settings(argv[1]);study.random_mesh_seed=settings.mesh_seed;int nx=std::stoi(argv[5]),ny=std::stoi(argv[6]);std::string level=argv[4];double delta=config.solver.source_regularisation_delta;
 std::ifstream in(argv[2]);std::vector<Case>cases;Case q;while(in>>q.mesh>>q.id>>q.alpha>>q.theta>>q.c)cases.push_back(q);
 std::ofstream coords(std::string(argv[3])+"/coordinates_"+level+".csv"),out(std::string(argv[3])+"/floor_"+level+".csv"),counts(std::string(argv[3])+"/counts_"+level+".csv");coords<<std::setprecision(17)<<"level,mesh_family,cell,x,y\n";out<<std::setprecision(17)<<"level,mesh_family,case_id,state,cell,x,y,stationary_distance,stationary_k,r_P,row_norm\n";counts<<std::setprecision(17)<<"level,mesh_family,case_id,state,n_floor,M2,tau\n";
 const vgt::gradients::polynomial::WLSQR2D method{vgt::gradients::WLSOptions2D{vgt::gradients::WLSWeighting2D::InverseDistanceSquared}};
 for(auto mesh:settings.mesh_families){auto mc=ps::make_mesh_config(config.mesh,mesh,settings.mesh_seed,nx,ny);gss::Fadeev cf{settings.calibration_alpha,settings.calibration_theta_degrees,Real{1}};
 // Geometry-only levels do not construct an AD tape or solve a linear system.
 if(level=="main"||level=="L4"){auto diagram=gss::MeshFactory::create_voronoi_diagram(mc);for(auto&cell:diagram.cells){auto pt=diagram.sites[cell.site_id.value].point;coords<<level<<','<<mesh<<','<<cell.volume_id<<','<<pt.x<<','<<pt.y<<'\n';}coords.flush();std::cout<<level<<' '<<mesh<<" cells="<<diagram.cells.size()<<std::endl;continue;}
 auto ws=ps::make_workspace(mc,cf,study.jacobian_stencil_radius);auto&top=ws.mesh.topology();for(size_t i=0;i<ws.exact.size();i++)coords<<level<<','<<mesh<<','<<i<<','<<top.coord_x[i]<<','<<top.coord_y[i]<<'\n';coords.flush();DiagJacobian jac{ws,method,delta,study,settings.source_derivative};
 for(auto row:cases)if(row.mesh==mesh){auto local=study;local.alpha=row.alpha;local.theta_degrees=row.theta;gss::Fadeev f{row.alpha,row.theta,Real{1}};refresh_case_data(ws,f);auto base=evaluate_base_source(ws,ws.exact,f,method,delta,local);auto comp=make_compensator(ws,ws.exact,base,row.c);ModifiedSource source{ws,f,method,delta,local,row.c,comp};for(int st=0;st<2;st++){auto state=st?perturbed_state(ws,ws.exact,1e-11):ws.exact;auto fl=diag::floor(jac,state,delta);auto values=jac.values(state,source);auto rn=diag::rownorm(ws.jacobian_pattern,values);std::string state_name=st?"PsiF_plus_1e-11":"PsiF";counts<<level<<','<<mesh<<','<<row.id<<','<<state_name<<','<<fl.count<<','<<fl.M2<<','<<fl.tau<<'\n';for(size_t i=0;i<state.size();i++)if(fl.g[i]<=fl.tau){auto [dist,k]=diag::stationary(top.coord_x[i],top.coord_y[i],row.theta);out<<level<<','<<mesh<<','<<row.id<<','<<state_name<<','<<i<<','<<top.coord_x[i]<<','<<top.coord_y[i]<<','<<dist<<','<<k<<','<<sqrt(fl.g[i]/fl.M2)<<','<<rn[i]<<'\n';}counts.flush();out.flush();}std::cout<<level<<' '<<mesh<<" case "<<row.id<<" complete"<<std::endl;}
 }
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
